import React, { useCallback, useEffect, useMemo, useState } from "react";
import { createRoot } from "react-dom/client";
import { jsPDF } from "jspdf";
import "./styles.css";

const CERTIFICATE_LOGO_DATA_URI = "data:image/png;base64,";

const TARGETS = [64, 128, 256, 512, 1024, 2048];
const MODES = [
  { id: "classic", title: "CLASSIC", desc: "Standard 2048 race", icon: "▦" },
  { id: "sprint", title: "SPRINT", desc: "Fast target challenge", icon: "⚡" },
  { id: "survival", title: "SURVIVAL", desc: "Keep the board alive", icon: "◇" }
];

const blankBoard = () => Array.from({ length: 4 }, () => Array(4).fill(0));

function addRandom(board) {
  const empty = [];
  board.forEach((row, r) => row.forEach((v, c) => v === 0 && empty.push([r, c])));
  if (!empty.length) return board;
  const [r, c] = empty[Math.floor(Math.random() * empty.length)];
  const next = board.map(row => [...row]);
  next[r][c] = Math.random() < 0.9 ? 2 : 4;
  return next;
}

function newBoard() {
  return addRandom(addRandom(blankBoard()));
}

function slideLine(line) {
  const values = line.filter(Boolean);
  const out = [];
  let gained = 0;
  for (let i = 0; i < values.length; i++) {
    if (values[i] === values[i + 1]) {
      const merged = values[i] * 2;
      out.push(merged);
      gained += merged;
      i++;
    } else {
      out.push(values[i]);
    }
  }
  while (out.length < 4) out.push(0);
  return { line: out, gained };
}

function moveBoard(board, dir) {
  const work = board.map(row => [...row]);
  let gained = 0;

  if (dir === "left" || dir === "right") {
    for (let r = 0; r < 4; r++) {
      let line = [...work[r]];
      if (dir === "right") line.reverse();
      const result = slideLine(line);
      line = result.line;
      if (dir === "right") line.reverse();
      work[r] = line;
      gained += result.gained;
    }
  } else {
    for (let c = 0; c < 4; c++) {
      let line = [0,1,2,3].map(r => work[r][c]);
      if (dir === "down") line.reverse();
      const result = slideLine(line);
      line = result.line;
      if (dir === "down") line.reverse();
      for (let r = 0; r < 4; r++) work[r][c] = line[r];
      gained += result.gained;
    }
  }

  const changed = JSON.stringify(board) !== JSON.stringify(work);
  return { board: changed ? addRandom(work) : board, gained, changed };
}

function hasMoves(board) {
  for (let r = 0; r < 4; r++) for (let c = 0; c < 4; c++) {
    if (!board[r][c]) return true;
    if (c < 3 && board[r][c] === board[r][c + 1]) return true;
    if (r < 3 && board[r][c] === board[r + 1][c]) return true;
  }
  return false;
}

function fmtTime(seconds) {
  const m = Math.floor(seconds / 60).toString().padStart(2, "0");
  const s = Math.floor(seconds % 60).toString().padStart(2, "0");
  return `${m}:${s}`;
}

function CornerDecor() {
  return <>
    <div className="corner corner-tl"><i/><i/><i/><i/></div>
    <div className="corner corner-br"><i/><i/><i/><i/></div>
    <div className="dots dots-tr">{Array.from({length:20},(_,i)=><b key={i}/>)}</div>
    <div className="dots dots-bl">{Array.from({length:16},(_,i)=><b key={i}/>)}</div>
  </>;
}

function Brand({ home = false }) {
  if (home) {
    return (
      <div className="brand home-brand">
        <img src="/nebuloid-logo-cropped.png" alt="Nebuloid Tech" />
      </div>
    );
  }
  return (
    <div className="brand">
      <div className="brand-mark" aria-hidden="true">
        <span className="n-mark">N</span><span className="t-mark">T</span>
      </div>
      <div className="brand-name">NEBULOID TECH</div>
      <div className="brand-rule"><span/><em>◇</em><span/></div>
    </div>
  );
}

function Button({children, primary=false, onClick, icon}) {
  return <button className={`menu-btn ${primary ? "primary":""}`} onClick={onClick}>
    <span className="btn-icon">{icon}</span><span>{children}</span>
  </button>;
}

function App() {
  const [page, setPage] = useState("welcome");
  const [name, setName] = useState("");
  const [target, setTarget] = useState(64);
  const [mode, setMode] = useState("classic");
  const [board, setBoard] = useState(newBoard);
  const [score, setScore] = useState(0);
  const [seconds, setSeconds] = useState(0);
  const [running, setRunning] = useState(false);
  const [paused, setPaused] = useState(false);
  const [result, setResult] = useState(null);
  const [certificateView, setCertificateView] = useState(null);
  const [certificateCountdown, setCertificateCountdown] = useState(null);
  const [certs, setCerts] = useState(() => {
    try { return JSON.parse(localStorage.getItem("2048-race-certs") || "{}"); } catch { return {}; }
  });

  const highest = useMemo(() => Math.max(...board.flat()), [board]);

  const resetGame = useCallback(() => {
    setBoard(newBoard());
    setScore(0);
    setSeconds(0);
    setPaused(false);
    setRunning(true);
    setResult(null);
  }, []);

  useEffect(() => {
    if (page !== "game" || !running || paused || result) return;
    const id = setInterval(() => setSeconds(s => s + 1), 1000);
    return () => clearInterval(id);
  }, [page, running, paused, result]);

  useEffect(() => {
    if (page !== "result" || !result?.won) {
      setCertificateCountdown(null);
      return;
    }

    setCertificateCountdown(5);

    const id = setInterval(() => {
      setCertificateCountdown(prev => {
        if (prev <= 1) {
          clearInterval(id);
          setCertificateView(result);
          setPage("certificate-view");
          return null;
        }
        return prev - 1;
      });
    }, 1000);

    return () => clearInterval(id);
  }, [page, result]);

  const finish = useCallback((won, finalScore=score, finalTime=seconds) => {
    setRunning(false);
    const item = { won, target, score: finalScore, time: finalTime, name: name.trim() || "Player", mode, date: new Date().toISOString() };
    setResult(item);
    if (won) {
      const next = { ...certs, [`${name.trim() || "Player"}-${target}`]: item };
      setCerts(next);
      localStorage.setItem("2048-race-certs", JSON.stringify(next));
    }
    setPage("result");
  }, [certs, mode, name, score, seconds, target]);

  const doMove = useCallback((dir) => {
    if (page !== "game" || paused || !running || result) return;
    const res = moveBoard(board, dir);
    if (!res.changed) {
      if (!hasMoves(board)) finish(false);
      return;
    }
    const nextScore = score + res.gained;
    setBoard(res.board);
    setScore(nextScore);
    if (res.board.flat().some(v => v >= target)) {
      finish(true, nextScore, seconds);
    } else if (!hasMoves(res.board)) {
      finish(false, nextScore, seconds);
    }
  }, [board, finish, page, paused, result, running, score, seconds, target]);

  useEffect(() => {
    const onKey = e => {
      // Keyboard controls are ONLY active on the game page.
      // Previously W/A/S/D were being captured globally, so those
      // letters could not be typed into the player-name input.
      if (page !== "game") return;

      const map = {
        ArrowLeft:"left",
        ArrowRight:"right",
        ArrowUp:"up",
        ArrowDown:"down",
        a:"left",
        d:"right",
        w:"up",
        s:"down",
        A:"left",
        D:"right",
        W:"up",
        S:"down"
      };

      if (map[e.key]) {
        e.preventDefault();
        doMove(map[e.key]);
      }

      if (e.key === "Escape") {
        setPaused(p => !p);
      }
    };
    window.addEventListener("keydown", onKey);
    return () => window.removeEventListener("keydown", onKey);
  }, [doMove, page]);

  function startFlow() {
    setPage("player");
  }

  function startGame() {
    if (!name.trim()) return;
    setPage("game");
    resetGame();
  }

  function certificateSvg(item, logoHref = CERTIFICATE_LOGO_DATA_URI) {
    const name = String(item?.name || "Player").trim() || "Player";
    const target = item?.target ?? 64;
    const time = fmtTime(item?.time);
    const score = item?.score ?? 0;
    const date = new Date(item?.date || Date.now()).toLocaleDateString();
    const nameSize = name.length > 24 ? 38 : name.length > 16 ? 44 : 50;
    const esc = value => String(value).replaceAll("&","&amp;").replaceAll("<","&lt;").replaceAll(">","&gt;").replaceAll('"',"&quot;").replaceAll("'","&apos;");
    return `<svg xmlns="http://www.w3.org/2000/svg" width="1600" height="1100" viewBox="0 0 1600 1100">
      <defs><linearGradient id="paper" x1="0" y1="0" x2="0" y2="1"><stop offset="0" stop-color="#fffefa"/><stop offset="1" stop-color="#FBFAF5"/></linearGradient><filter id="shadow"><feDropShadow dx="0" dy="8" stdDeviation="10" flood-color="#000" flood-opacity=".1"/></filter></defs>
      <rect width="1600" height="1100" fill="url(#paper)"/>
      <rect x="25" y="25" width="1550" height="1050" fill="none" stroke="#0D0F0F" stroke-width="7"/><rect x="39" y="39" width="1522" height="1022" fill="none" stroke="#C79A35" stroke-width="2"/>
      <polygon points="25,25 450,25 270,165 25,165" fill="#0D0F0F"/><polygon points="105,25 450,25 305,140 105,140" fill="#176F3F"/>
      <path d="M25 285 L25 165 L305 25 M65 340 L65 205 L340 25 M100 355 L100 230 L365 55" fill="none" stroke="#C79A35" stroke-width="3"/>
      <polygon points="1575,1075 1150,1075 1330,935 1575,935" fill="#0D0F0F"/><polygon points="1495,1075 1150,1075 1295,960 1495,960" fill="#176F3F"/>
      <path d="M1575 815 L1575 935 L1295 1075 M1535 760 L1535 895 L1260 1075 M1500 745 L1500 870 L1235 1045" fill="none" stroke="#C79A35" stroke-width="3"/>
      <g fill="#176F3F">${Array.from({length:16},(_,i)=>`<circle cx="${1390+(i%4)*27}" cy="${125+Math.floor(i/4)*27}" r="3.2"/>`).join("")}${Array.from({length:16},(_,i)=>`<circle cx="${105+(i%4)*27}" cy="${915+Math.floor(i/4)*27}" r="3.2"/>`).join("")}</g>
      <image href="${logoHref}" x="675" y="58" width="250" height="155" preserveAspectRatio="xMidYMid meet"/>
      <line x1="520" y1="265" x2="1080" y2="265" stroke="#176F3F" stroke-width="3"/>
      <text x="800" y="315" text-anchor="middle" font-family="Arial" font-weight="700" font-size="25" letter-spacing="5" fill="#0D0F0F">NEBULOID TECH</text>
      <text x="785" y="410" text-anchor="end" font-family="Arial" font-weight="800" font-size="96" fill="#0D0F0F">2048</text><text x="815" y="410" text-anchor="start" font-family="Arial" font-weight="800" font-size="96" fill="#176F3F">RACE</text>
      <polygon points="350,445 1250,445 1300,500 1250,555 350,555 300,500" fill="#C79A35"/><polygon points="370,452 1230,452 1265,500 1230,548 370,548 335,500" fill="#176F3F"/>
      <text x="800" y="512" text-anchor="middle" font-family="Arial" font-weight="700" font-size="30" letter-spacing="5" fill="#fff">CERTIFICATE OF ACHIEVEMENT</text>
      <text x="800" y="610" text-anchor="middle" font-family="Arial" font-size="25" fill="#4D4D4D">This certifies that</text>
      <line x1="430" y1="670" x2="610" y2="670" stroke="#C79A35" stroke-width="2"/><line x1="990" y1="670" x2="1170" y2="670" stroke="#C79A35" stroke-width="2"/>
      <text x="800" y="690" text-anchor="middle" font-family="Arial" font-weight="800" font-size="${nameSize}" fill="#176F3F">${esc(name)}</text>
      <line x1="640" y1="725" x2="960" y2="725" stroke="#C9C9C1" stroke-width="2" stroke-dasharray="8 8"/>
      <text x="800" y="785" text-anchor="middle" font-family="Arial" font-size="28" fill="#0D0F0F">reached Target <tspan font-weight="700" fill="#176F3F">${target}</tspan> in <tspan font-weight="700" fill="#176F3F">${time}</tspan> with a score of <tspan font-weight="700" fill="#176F3F">${score}.</tspan></text>
      <g filter="url(#shadow)"><circle cx="800" cy="900" r="84" fill="#C79A35"/><circle cx="800" cy="900" r="68" fill="#0D0F0F" stroke="#C79A35" stroke-width="5"/><circle cx="800" cy="900" r="55" fill="none" stroke="#C79A35" stroke-width="2"/>
        <text x="800" y="858" text-anchor="middle" font-size="23" fill="#C79A35">★ ★ ★</text>
        <path d="M774 874 h52 v25 c0 14 -11 24 -26 24 s-26 -10 -26 -24 z" fill="#C79A35"/><path d="M774 880 h-18 c0 19 9 29 24 29 M826 880 h18 c0 19 -9 29 -24 29" fill="none" stroke="#C79A35" stroke-width="6"/><rect x="795" y="921" width="10" height="13" fill="#C79A35"/><rect x="780" y="933" width="40" height="7" rx="3" fill="#C79A35"/>
        <text x="800" y="957" text-anchor="middle" font-family="Arial" font-weight="800" font-size="24" fill="#fff">${target}</text><text x="800" y="972" text-anchor="middle" font-family="Arial" font-weight="700" font-size="10" letter-spacing="2" fill="#C79A35">TARGET</text>
      </g>
      <polygon points="748,978 790,982 760,1052 720,1020" fill="#176F3F" stroke="#C79A35" stroke-width="2"/><polygon points="810,982 852,978 880,1020 840,1052" fill="#176F3F" stroke="#C79A35" stroke-width="2"/>
      <text x="420" y="975" text-anchor="middle" font-family="Arial" font-weight="700" font-size="23">${esc(date)}</text><line x1="320" y1="995" x2="520" y2="995" stroke="#C79A35" stroke-width="2"/><text x="420" y="1025" text-anchor="middle" font-family="Arial" font-weight="700" font-size="16" letter-spacing="5" fill="#176F3F">DATE</text>
      <text x="1180" y="975" text-anchor="middle" font-size="39" font-style="italic" font-family="cursive">Nebuloid Tech</text><line x1="1080" y1="995" x2="1280" y2="995" stroke="#0D0F0F" stroke-width="2"/><line x1="1060" y1="1012" x2="1300" y2="1012" stroke="#C79A35" stroke-width="2"/><text x="1180" y="1040" text-anchor="middle" font-family="Arial" font-weight="700" font-size="16" letter-spacing="5" fill="#176F3F">AUTHORIZED SIGNATURE</text>
    </svg>`;
  }

  async function downloadCertificate(item) {
    const svg = certificateSvg(item);

    const svgDataUrl =
      "data:image/svg+xml;charset=utf-8," +
      encodeURIComponent(svg);

    try {
      const img = new Image();
      img.decoding = "async";

      await new Promise((resolve, reject) => {
        img.onload = resolve;
        img.onerror = () => reject(new Error("Certificate preview could not be rendered."));
        img.src = svgDataUrl;
      });

      if (img.decode) {
        try { await img.decode(); } catch (_) {}
      }

      const canvas = document.createElement("canvas");
      canvas.width = 2400;
      canvas.height = 1650;

      const ctx = canvas.getContext("2d");
      if (!ctx) throw new Error("Canvas is not available in this browser.");

      ctx.fillStyle = "#FBFAF5";
      ctx.fillRect(0, 0, canvas.width, canvas.height);
      ctx.drawImage(img, 0, 0, canvas.width, canvas.height);

      const png = canvas.toDataURL("image/png", 1);

      const doc = new jsPDF({
        orientation: "landscape",
        unit: "mm",
        format: "a4",
        compress: true
      });

      doc.addImage(png, "PNG", 0, 0, 297, 204.5, undefined, "FAST");

      const name = String(item?.name || "Player").trim() || "Player";
      const safeName = name.replace(/[^a-z0-9]/gi, "_");
      const targetValue = item?.target ?? 64;

      doc.save(`2048-Race-${safeName}-Target-${targetValue}.pdf`);
    } catch (error) {
      console.error("Certificate download failed:", error);
      alert("Certificate download failed. Please try again.");
    }
  }

  const certItems = Object.values(certs);

  return (
    <div className="app">
      <header className="window-bar"><span className="window-icon">▦</span><span>2048 Race</span><div className="window-controls"><span>—</span><span>□</span><span>×</span></div></header>

      {page === "welcome" && <main className="screen welcome"><CornerDecor/><Brand home/>
        <section className="hero">
          <h1>2048</h1><h2>R A C E</h2>
          <div className="hero-rule"><span/> <b>REACH • RACE • ACHIEVE</b> <span/></div>
        </section>
        <div className="menu">
          <Button primary icon="▶" onClick={startFlow}>START RACE</Button>
          <Button icon="▣" onClick={()=>setPage("certificates")}>CERTIFICATES</Button>
          <Button icon="ⓘ" onClick={()=>setPage("how")}>HOW TO PLAY</Button>
          <Button icon="↪" onClick={()=>window.close()}>EXIT</Button>
        </div>
        <p className="bottom-note">★　Every genuine target unlocks a personalized certificate.　★</p>
      </main>}

      {page === "player" && <main className="screen player-page">
        <CornerDecor/>
        <div className="player-brand">
          <img src="/nebuloid-logo-cropped.png" alt="Nebuloid Tech" />
        </div>

        <div className="player-content">
          <div className="player-heading">
            <div className="player-title-row"><span></span><h1>2048 RACE</h1><span></span></div>
            <h2>PLAYER SETUP</h2>
            <p>Enter the name that will appear on the certificate.</p>
          </div>

          <div className="player-form">
            <div className="player-input-wrap">
              <span className="player-user-icon" aria-hidden="true">
                <i></i><b></b>
              </span>
              <input
                autoFocus
                value={name}
                onChange={e=>setName(e.target.value)}
                placeholder="Type player name..."
                maxLength={30}
                onKeyDown={e=>e.key==="Enter"&&name.trim()&&setPage("target")}
              />
            </div>

            <div className="player-actions">
              <Button onClick={()=>setPage("welcome")} icon="←">BACK</Button>
              <Button primary onClick={()=>name.trim()&&setPage("target")} icon="→">CONTINUE</Button>
            </div>

            <div className="player-enter-hint">
              <span className="enter-key">ENTER</span>
              <span>Press <b>ENTER</b> to continue</span>
            </div>
          </div>
        </div>
      </main>}

      {page === "target" && <main className="screen subpage"><CornerDecor/><div className="compact-head">
          <img
            src="/nebuloid-logo-cropped.png"
            alt="Nebuloid Tech"
            style={{
              display: "block",
              width: "220px",
              height: "auto",
              margin: "0 auto"
            }}
          />
        </div>
        <div className="panel wide"><div className="eyebrow">RACE SETUP · 02</div><h1>SELECT TARGET</h1><p>Choose the number you must reach to finish the race.</p>
          <div className="target-grid">{TARGETS.map(t=><button key={t} className={`target-card ${target===t?"selected":""}`} onClick={()=>setTarget(t)}><strong>{t}</strong><span>TARGET</span></button>)}</div>
          <div className="actions"><Button onClick={()=>setPage("player")} icon="←">BACK</Button><Button primary onClick={()=>setPage("mode")} icon="→">CONTINUE</Button></div>
        </div>
      </main>}

      {page === "mode" && <main className="screen subpage"><CornerDecor/><div className="panel wide"><div className="eyebrow">RACE SETUP · 03</div><h1>SELECT MODE</h1><p>Choose how you want to race.</p>
        <div className="mode-grid">{MODES.map(m=><button key={m.id} className={`mode-card ${mode===m.id?"selected":""}`} onClick={()=>setMode(m.id)}><span className="mode-icon">{m.icon}</span><strong>{m.title}</strong><small>{m.desc}</small></button>)}</div>
        <div className="actions"><Button onClick={()=>setPage("target")} icon="←">BACK</Button><Button primary onClick={()=>setPage("confirm")} icon="→">CONTINUE</Button></div>
      </div></main>}

      {page === "confirm" && <main className="screen subpage"><CornerDecor/><div className="panel confirm"><div className="eyebrow">FINAL CHECK</div><h1>RACE CONFIRMATION</h1>
        <div className="summary"><div><small>PLAYER</small><strong>{name}</strong></div><div><small>TARGET</small><strong>{target}</strong></div><div><small>MODE</small><strong>{mode.toUpperCase()}</strong></div></div>
        <p>Reach the target as fast as possible. A genuine completion unlocks your personalized certificate.</p>
        <div className="actions"><Button primary onClick={startGame} icon="▶">START RACE</Button><Button onClick={()=>setPage("mode")} icon="←">BACK</Button></div>
      </div></main>}

      {page === "game" && <main className="screen game-screen"><div className="game-top"><button className="small-btn" onClick={()=>setPaused(p=>!p)}>{paused?"RESUME":"PAUSE"}</button><div><span className="stat-label">TARGET</span><strong>{target}</strong></div><div><span className="stat-label">TIME</span><strong>{fmtTime(seconds)}</strong></div><div><span className="stat-label">SCORE</span><strong>{score}</strong></div><button className="small-btn" onClick={resetGame}>RESTART</button></div>
        <div className="game-content"><div className="game-title"><span>2048 RACE</span><h1>{name}</h1><p>Reach <b>{target}</b> · {mode.toUpperCase()}</p></div>
          <div className="board-wrap"><div className="board">{board.map((row,r)=>row.map((v,c)=><div key={`${r}-${c}`} className={`tile tile-${v}`}>{v||""}</div>))}</div>{paused&&<div className="pause-overlay"><strong>PAUSED</strong><span>Press ESC or RESUME</span></div>}</div>
          <div className="game-help">Use <b>W A S D</b> or <b>Arrow Keys</b> to move</div>
        </div>
      </main>}

      {page === "result" && result && <main className="screen result-screen"><CornerDecor/><div className="result-card">
        <div className="trophy">♛</div><div className="result-status">{result.won ? "TARGET REACHED!" : "RACE OVER"}</div>
        <div className="result-target">{result.target}</div>
        <div className="result-grid"><div><small>PLAYER</small><strong>{result.name}</strong></div><div><small>TIME</small><strong>{fmtTime(result.time)}</strong></div><div><small>SCORE</small><strong>{result.score}</strong></div></div>
        <div className="result-actions">{result.won && <Button primary onClick={()=>{setCertificateView(result);setPage("certificate-view")}} icon="▣">VIEW CERTIFICATE</Button>}<Button onClick={()=>{const next=TARGETS[TARGETS.indexOf(target)+1]; if(next){setTarget(next);setPage("confirm")}else setPage("welcome")}} icon="→">{TARGETS.indexOf(target)<TARGETS.length-1?"NEXT TARGET":"MAIN MENU"}</Button><Button onClick={()=>setPage("welcome")} icon="⌂">MAIN MENU</Button></div>
        {result.won && certificateCountdown !== null && (
          <div
            style={{
              marginTop: "18px",
              padding: "10px 18px",
              border: "1px solid #C79A35",
              borderRadius: "8px",
              textAlign: "center",
              fontSize: "18px",
              fontWeight: "700",
              background: "#fffefa"
            }}
          >
            Certificate preview opens in <span style={{fontSize: "24px", color: "#176F3F"}}>{certificateCountdown}</span> second{certificateCountdown === 1 ? "" : "s"}
          </div>
        )}
      </div></main>}

      {page === "certificate-view" && certificateView && <main className="screen certificate-screen">
        <CornerDecor/>
        <div className="certificate-page-head">
          <div>
            <div className="eyebrow">ACHIEVEMENT</div>
            <h1>CERTIFICATE</h1>
            <p>{certificateView.name} · Target {certificateView.target}</p>
          </div>
        </div>

        <div className="certificate-preview-shell">
          <div
            className="certificate-svg-preview"
            dangerouslySetInnerHTML={{__html: certificateSvg(certificateView)}}
          />
        </div>

        <div className="certificate-actions">
          <Button primary onClick={()=>downloadCertificate(certificateView)} icon="⇩">DOWNLOAD CERTIFICATE</Button>
          <Button onClick={()=>setPage("certificates")} icon="←">BACK TO CERTIFICATES</Button>
        </div>
      </main>}

      {page === "certificates" && <main className="screen subpage"><CornerDecor/><div className="panel wide"><div className="eyebrow">ACHIEVEMENTS</div><h1>CERTIFICATES</h1><p>Every genuine target completion is stored here.</p>
        {certItems.length===0 ? <div className="empty">No certificates yet. Win a race to unlock your first one.</div> :
          <div className="cert-list">{certItems.map((c,i)=><div className="cert-row" key={i}><div><strong>{c.name}</strong><span>Target {c.target} · {fmtTime(c.time)} · Score {c.score}</span></div><button onClick={()=>{setCertificateView(c);setPage("certificate-view")}}>VIEW</button></div>)}</div>}
        <div className="actions"><Button onClick={()=>setPage("welcome")} icon="←">MAIN MENU</Button></div>
      </div></main>}

      {page === "how" && <main className="screen subpage"><CornerDecor/><div className="panel wide how"><div className="eyebrow">GUIDE</div><h1>HOW TO PLAY</h1><div className="steps"><div><b>01</b><strong>Choose your player</strong><span>Your name is printed on the certificate.</span></div><div><b>02</b><strong>Select a target</strong><span>Targets range from 64 to 2048.</span></div><div><b>03</b><strong>Combine matching tiles</strong><span>Move the board with WASD or Arrow Keys.</span></div><div><b>04</b><strong>Reach it fast</strong><span>Finish the target to unlock your certificate.</span></div></div><div className="actions"><Button onClick={()=>setPage("welcome")} icon="←">MAIN MENU</Button></div></div></main>}
    </div>
  );
}

createRoot(document.getElementById("root")).render(<App />);